1	/**
2	 * Compile the `.css`-authored component records (`src/components/*.css`, `src/utilities/*.css`) into a
3	 * single generated TS module of string constants (`src/generated/component-styles.ts`). The `.css` files
4	 * are the authoring source of truth (real CSS — native stylelint/cssdoc/editor support); each carries the
5	 * `PFX-` class-prefix sentinel. The thin record wrappers import these consts and do
6	 * `raw.replaceAll(SENTINEL, p)` inside their `css: (p) => …` builder, so the prefix is applied at build
7	 * time exactly where `${p}` used to interpolate.
8	 *
9	 * Unlike the web-components `scripts/styles.ts` this module models, the cssdoc `/** … *\/` doc comments
10	 * are RETAINED — here they are load-bearing (they flow into `generated/components.css`, which
11	 * `docs/scripts/build-css-api.ts` parses for the CSS-API pages). Content is emitted verbatim; the runtime
12	 * pipeline (`define.ts`) normalizes leading/trailing whitespace, so byte-identity of the emitted sheets
13	 * is preserved.
14	 *
15	 * `vp pack` (rolldown) doesn't resolve Vite's `?raw` query, so a generated `.ts` module is the portable
16	 * way to get the CSS text into the published bundle. Run before `vp pack` / `generate` / `check` / `test`.
17	 */
18	import { mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
19	import { join, resolve } from "node:path";
20	import postcss from "postcss";
21	import { themeCustomMedia } from "@pantoken/plugin-theme-custom-media";
22	
23	const srcDir = resolve(import.meta.dirname, "../src");
24	const sources = [join(srcDir, "components"), join(srcDir, "utilities")];
25	const THEMES = ["rebrand", "canvas", "canvasHighContrast"] as const;
26	
27	/** `screen-reader-content.css` → `screenReaderContent`. */
28	const toIdentifier = (file: string): string =>
29	  file.replace(/\.css$/u, "").replace(/-([a-z0-9])/gu, (_m, c: string) => c.toUpperCase());
30	
31	const entries: string[] = [];
32	for (const dir of sources) {
33	  for (const file of readdirSync(dir)
34	    .filter((f) => f.endsWith(".css"))
35	    .sort()) {
36	    const css = readFileSync(join(dir, file), "utf8");
37	    const id = toIdentifier(file);
38	    const byTheme: Record<(typeof THEMES)[number], string> = {
39	      rebrand: css,
40	      canvas: css,
41	      canvasHighContrast: css,
42	    };
43	    for (const theme of THEMES) {
44	      byTheme[theme] = postcss([themeCustomMedia({ theme })]).process(css, { from: undefined }).css;
45	    }
46	    entries.push(`export const ${id}ByTheme = ${JSON.stringify(byTheme)} as const;`);
47	    entries.push(`export const ${id} = ${id}ByTheme.rebrand;`);
48	  }
49	}
50	
51	const outDir = join(srcDir, "generated");
52	mkdirSync(outDir, { recursive: true });
53	writeFileSync(
54	  join(outDir, "component-styles.ts"),
55	  `// AUTO-GENERATED from src/{components,utilities}/*.css by scripts/component-styles.ts — do not edit.\n${entries.join(
56	    "\n",
57	  )}\n`,
58	);
59	console.log(
60	  `✓ components: wrote src/generated/component-styles.ts (${String(entries.length)} stylesheets)`,
61	);
