1	/**
2	 * `@pantoken/plugin-stacking` — named z-index depths.
3	 *
4	 * InstUI's `View` exposes a stacking scale (`deepest`, `below`, `above`, `topmost`) so layers stack
5	 * predictably instead of by hand-tuned magic numbers. This plugin surfaces that scale two ways: it
6	 * emits `--instui-stacking-<level>` tokens (resolved to concrete z-index values from the shipped
7	 * `--instui-component-view-stacking-*` tokens), and a matching set of `.instui-stack-<level>` utility
8	 * classes.
9	 *
10	 * Both hooks are defined, so the consumer chooses the layer: add it to `buildTokens` to bake the
11	 * `--instui-stacking-*` records into every output, or to `toCss` (the css hook self-defines them, so
12	 * the `.instui-stack-*` classes stand alone).
13	 *
14	 * @example
15	 * ```ts
16	 * import { toCss } from "@pantoken/css";
17	 * import { byTheme } from "@pantoken/tokens";
18	 * import { stacking } from "@pantoken/plugin-stacking";
19	 *
20	 * const css = toCss(byTheme("rebrand"), { plugins: [stacking()] });
21	 * // :root { --instui-stacking-topmost: … } + .instui-stack-topmost { z-index: … }
22	 * ```
23	 *
24	 * @module
25	 * @beta
26	 */
27	import { definePlugin, makeResolver } from "@pantoken/plugin-kit";
28	import { byTheme } from "@pantoken/tokens";
29	import type { PantokenPlugin, Theme, Token, TokenInput } from "@pantoken/model";
30	
31	/** The stacking depths, deepest → topmost, from InstUI's view stacking scale. */
32	export const STACKING_LEVELS: readonly string[] = ["deepest", "below", "above", "topmost"];
33	
34	/** Options for the {@link stacking} plugin. */
35	export interface StackingOptions {
36	  /** The theme whose shipped IR seeds reference resolution (default `"rebrand"` in the css hook). */
37	  theme?: Theme;
38	  /** Where the css-hook rules land relative to the stylesheet: `"append"` (default) or `"prepend"`. */
39	  position?: "append" | "prepend";
40	}
41	
42	/**
43	 * Create the stacking plugin.
44	 *
45	 * @param options - {@link StackingOptions}.
46	 * @returns A {@link PantokenPlugin} with `tokens` and `css` hooks.
47	 */
48	export function stacking(options: StackingOptions = {}): PantokenPlugin {
49	  const position = options.position ?? "append";
50	
51	  function definitions(tokens: readonly Token[], theme: Theme): TokenInput[] {
52	    const resolve = makeResolver(byTheme(theme), { overrides: tokens });
53	    return STACKING_LEVELS.map((level) => ({
54	      name: `--instui-stacking-${level}`,
55	      value: resolve(`var(--instui-component-view-stacking-${level})`),
56	    }));
57	  }
58	
59	  const rules = STACKING_LEVELS.map(
60	    (level) => `.instui-stack-${level} { z-index: var(--instui-stacking-${level}); }`,
61	  ).join("\n");
62	
63	  return definePlugin({
64	    name: "@pantoken/plugin-stacking",
65	    tokens: ({ tokens, theme, define }) => [
66	      ...tokens,
67	      ...definitions(tokens, options.theme ?? theme).map((d) => define(d)),
68	    ],
69	    css: ({ tokens }) => {
70	      const present = new Set(tokens.map((t) => t.name));
71	      const declarations = definitions(tokens, options.theme ?? "rebrand")
72	        .filter((d) => !present.has(d.name))
73	        .map((d): [string, string] => [d.name, d.value]);
74	      return {
75	        marker: "pantoken:stacking",
76	        ...(declarations.length ? { declarations } : {}),
77	        [position]: rules,
78	      };
79	    },
80	  });
81	}
82	
83	export default stacking;
