1	/**
2	 * Shared test helper: assert a {@link Definition} is well-formed — its emitted CSS parses to exactly
3	 * one `@cssdoc/core` record of the declared kind/name, and every `var(--instui-*)` it references exists
4	 * in the token IR. Reuses the real cssdoc parser (not a regex) so the per-record guard matches the
5	 * emitter's own view of the record.
6	 *
7	 * @module
8	 */
9	import { CssDocConfigFile } from "@cssdoc/config";
10	import { parseCssDocs } from "@cssdoc/core";
11	import { byTheme } from "@pantoken/tokens";
12	import { unknownReferences } from "@pantoken/utils";
13	import type { Definition } from "../src/lib/define.ts";
14	
15	// The repo's shared cssdoc.json (root) — loaded once so the per-record guard parses with the same tag
16	// configuration the docs emitter and lint plugins use. `loadForFolder` walks up from the tests dir.
17	const configuration = CssDocConfigFile.loadForFolder(import.meta.dirname).toConfiguration();
18	
19	// Elevation shadows and the focus ring are declared by the sheets themselves, not the base token IR.
20	const isLocal = (ref: string): boolean =>
21	  ref.startsWith("--instui-elevation-") || ref.startsWith("--instui-focus-outline-");
22	
23	/** Assert a definition is well-formed; throws (naming the record) on the first problem. */
24	export function validate(def: Definition): void {
25	  const css = def.css({ prefix: "instui", theme: "rebrand" });
26	  const entries = parseCssDocs(css, { configuration });
27	  if (entries.length !== 1)
28	    throw new Error(`${def.name}: expected exactly one cssdoc record, got ${entries.length}`);
29	  const [entry] = entries;
30	  if (entry.kind !== def.kind)
31	    throw new Error(`${def.name}: parsed kind "${entry.kind}" ≠ declared "${def.kind}"`);
32	  if (entry.name !== def.name)
33	    throw new Error(`${def.name}: parsed name "${entry.name}" ≠ declared "${def.name}"`);
34	  for (const theme of ["rebrand", "canvas", "canvasHighContrast"] as const) {
35	    const themedCss = def.css({ prefix: "instui", theme });
36	    const drift = unknownReferences(themedCss, byTheme(theme)).filter((r) => !isLocal(r));
37	    if (drift.length)
38	      throw new Error(`${def.name} (${theme}): unknown token reference(s): ${drift.join(", ")}`);
39	  }
40	}
