210	  resolveValue = makeResolver([...tokens, ...localTokens]);
211	
212	  // Load the repo's shared cssdoc.json (root) — the single declarative config that also drives the
213	  // lint plugins and the per-record test guard, so docs, lint, and tests agree on the record model and
214	  // section order. `configFile` feeds `emitCssApi` (parse config + `render` section order/heading);
215	  // `configuration` is its parse view, reused locally for `parseCssDocs`.
216	  const componentsRoot = join(generatedCssDir, "..");
217	  const configFile = CssDocConfigFile.loadForFolder(repoRoot);
218	  const configuration = configFile.toConfiguration();
219	
220	  // `**Source:**` link → each record's authoring `.ts`. `## Usage` import → the sheet the record ships
221	  // in (a record's own sheet, resolved by parsing each of the four sheets for its record names).
222	  const resolveSource = makeResolveSource(sourceMap(componentSources(componentsRoot)));
223	  const recordSheet = new Map<string, string>();
224	  for (const sheet of sheets)
225	    for (const e of parseCssDocs(readCss(sheet), { configuration })) recordSheet.set(e.name, sheet);
226	  const importSnippet = (entry: CssDocEntry): string | undefined => {
227	    const sheet = recordSheet.get(entry.name);
228	    if (!sheet) return undefined;
229	    if (entry.kind === "component") {
230	      return [
231	        `@import "@pantoken/components/${sheet}";`,
232	        `@import "@pantoken/components/${entry.name}.css";`,
233	      ].join("\n");
234	    }
