1	/**
2	 * `defineComponent`/`defineUtility`/`defineRule`/`defineDeclaration` — the ergonomic wrappers over
3	 * {@link record}. Each takes the record metadata plus a `css: (p) => string` body builder and returns
4	 * a {@link Definition}: `rules(p)` (doc block + body, what the aggregator concatenates) and
5	 * `css(options)` (the wrapped standalone sheet, what the exported `xxxCss` returns).
6	 *
7	 * @module
8	 */
9	import type { CssRecordKind } from "@cssdoc/core";
10	import {
11	  deprecatedAliasPairs,
12	  withAliases,
13	  withSizeAliases,
14	  withSizeAliasDocs,
15	} from "./aliases.ts";
16	import { ns, wrap, type ComponentOptions } from "./helpers.ts";
17	
18	export interface Definition {
19	  name: string;
20	  kind: CssRecordKind;
21	  /** Doc block + CSS body at the given (already `ns()`-joined) prefix — concatenated by the aggregator. */
22	  rules(this: void, prefix: string, options?: ComponentOptions): string;
23	  /**
24	   * The standalone, header-wrapped stylesheet — what the exported `xxxCss` returns. Declared `this: void`
25	   * because it's a plain closure (no receiver): callers bind it as `export const buttonCss = button.css`,
26	   * so the annotation tells the linter the free-floating reference is safe.
27	   */
28	  css(this: void, options?: ComponentOptions): string;
29	}
30	
31	/** A record definition's input: the record's programmatic name + its CSS builder. */
32	export interface DefineInput {
33	  /** The record's identity — used for the standalone-sheet header, the exports, and `validate()`. */
34	  name: string;
35	  /**
36	   * Build the full record for the `ns()`-joined prefix `p`: a leading `/** … *\/` cssdoc doc comment
37	   * (prefix-independent) followed by the CSS body, e.g. ``(p) => `/** @component menu … *\/\n.${p}menu {…}` ``.
38	   */
39	  css: (p: string, options?: ComponentOptions) => string;
40	}
41	
42	/**
43	 * Split a record's leading `/** … *\/` doc comment from its CSS body. The alias post-processors scan
44	 * for `{ … }` rule bodies, so they must never see the comment's `{@link …}` braces — `make()` runs them
45	 * on the body alone and recombines. Tolerates leading whitespace before `/**` (an authored template
46	 * literal often opens with a newline); drops the single newline separating the comment from the body.
47	 */
48	function splitLeadingDocComment(raw: string): { comment: string; body: string } {
49	  const m = raw.match(/^\s*\/\*\*[\s\S]*?\*\//u);
50	  if (!m) return { comment: "", body: raw };
51	  return { comment: m[0].replace(/^\s+/u, ""), body: raw.slice(m[0].length).replace(/^\n/u, "") };
52	}
53	
54	function make(kind: CssRecordKind, input: DefineInput): Definition {
55	  const { css: cssBuilder } = input;
56	  // Deprecated-alias twins are discovered from the doc comment; the comment is prefix-independent, so
57	  // parse the record once (any prefix) rather than per `rules()` call.
58	  const aliasPairs = deprecatedAliasPairs(cssBuilder("instui-", { theme: "rebrand" }));
59	  // Append the size-alias and deprecated-alias twins to the CSS BODY ONLY (never the comment), so each
60	  // alias documents on this record's own page and the brace scanners never see the `{@link …}` braces.
61	  const rules = (prefix: string, options: ComponentOptions = {}): string => {
62	    const { comment, body } = splitLeadingDocComment(cssBuilder(prefix, options));
63	    // Auto-document the long-form size twins withSizeAliases appends, so they aren't undocumented.
64	    return `${withSizeAliasDocs(comment, body)}\n${withAliases(withSizeAliases(body), aliasPairs).trim()}\n`;
65	  };
66	  return {
67	    name: input.name,
68	    kind,
69	    rules,
70	    css: (options: ComponentOptions = {}) => {
71	      const prefix = options.prefix || "";
72	      return wrap(input.name, prefix, rules(ns(prefix), options));
73	    },
74	  };
75	}
76	
77	export const defineComponent = (input: DefineInput): Definition => make("component", input);
78	export const defineUtility = (input: DefineInput): Definition => make("utility", input);
79	export const defineRule = (input: DefineInput): Definition => make("rule", input);
80	export const defineDeclaration = (input: DefineInput): Definition => make("declaration", input);
