1	/**
2	 * Detect translation drift: English content whose translation is missing or stale.
3	 *
4	 * The committed translation memory (`docs/i18n-cache/<locale>.<namespace>.json`) is content-addressed
5	 * — a unit's key is `sha256(kind \0 source)`. So the key for a block of *current* English is present
6	 * only if that exact text was translated (and the prose poison-cache guard means a prose key is only
7	 * ever written by a real `:claude` run, never by the glossary passthrough). Edit the English and its
8	 * hash changes, so the old entry no longer matches: a missing key == untranslated or drifted.
9	 *
10	 * This check derives the keys the current English needs and asserts each is in the cache. It is
11	 * adapter-free — it never constructs an adapter or spawns `claude` — so it is safe to run in CI
12	 * (`docs/conventions/build-and-docs.md`: never wire the `:claude` cold pass into CI). Fill drift
13	 * locally with `vp run docs:locales:translate`, then commit the updated cache.
14	 *
15	 * Guides drift is pure (the English source is committed). API drift needs the generated EN tree
16	 * (`docs/api/**`), so run it after `docs:api:en`; if `docs/api` is absent it is skipped with a note.
17	 *
18	 * @module
19	 */
20	import { existsSync, readFileSync, readdirSync, statSync } from "node:fs";
21	import { join, relative } from "node:path";
22	import { LOCALES } from "../.vitepress/i18n.ts";
23	import { collectUnits, segmentMarkdown } from "./segment-markdown.ts";
24	import { keyFor } from "./translation-memory.ts";
