30	
31	const targets = Object.keys(LOCALES).filter((key) => key !== "root");
32	
33	interface Missing {
34	  file: string;
35	  kind: string;
36	  sample: string;
37	}
38	
39	const loadCacheKeys = (locale: string, namespace: string): Set<string> => {
40	  const path = join(cacheDir, `${locale}.${namespace}.json`);
41	  if (!existsSync(path)) return new Set();
42	  const parsed = JSON.parse(readFileSync(path, "utf8")) as { entries?: Record<string, string> };
43	  return new Set(Object.keys(parsed.entries ?? {}));
44	};
45	
46	const walkMarkdown = (dir: string): string[] => {
47	  if (!existsSync(dir)) return [];
48	  const out: string[] = [];
49	  for (const name of readdirSync(dir)) {
50	    const full = join(dir, name);
51	    if (statSync(full).isDirectory()) out.push(...walkMarkdown(full));
52	    else if (full.endsWith(".md")) out.push(full);
53	  }
54	  return out;
55	};
