// The `.release-plan.*` / `.release-packages.txt` artifacts are gitignored (regenerated by release.yml
// each run), so they're intentionally not staged — only the version bumps and changelogs are committed.
run("git", ["add", ...releasePackageJsonFiles, ...changedChangelogFiles, "CHANGELOG.md"], {
  cwd: rootDir,
});

// Conventional-commit subject: commitlint requires an allowed type and a <=100-char header, so use a
// `chore(release):` type with the primary tag in the subject and the full tag list in the body.
const commitSubject =
  tags.length === 1
    ? `chore(release): ${tags[0]}`
    : `chore(release): ${tags[0]} (+${tags.length - 1} more)`;
run("git", ["commit", "-m", commitSubject, "-m", tags.join("\n")], { cwd: rootDir });

